        lblSession.setStyle(
                "-fx-background-color: #475569; " +
                        "-fx-text-fill: white; " +
                        "-fx-background-radius: 12; " +
                        "-fx-padding: 3 10; " +
                        "-fx-font-size: 12px;"
        );

        HBox row = new HBox();

