        VBox dialog = new VBox(25);
        dialog.setMaxSize(450, 520);
        dialog.setStyle("-fx-background-color: #1a2230; -fx-background-radius: 15; " +
                "-fx-border-color: #334155; -fx-border-radius: 15; " +
